import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.kOe0DhAP.js";const _=JSON.parse('{"title":"核心设计","description":"订单、周期、价格证据和结算事实应能相互关联。","frontmatter":{"title":"核心设计","description":"订单、周期、价格证据和结算事实应能相互关联。"},"headers":[],"relativePath":"08/0803/080003.md","filePath":"08/0803/080003.md"}'),i={name:"08/0803/080003.md"};function c(s,a,n,d,l,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<div class="doc-eyebrow">期权手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h1><div class="doc-lead">订单、周期、价格证据和结算事实应能相互关联。</div><h2 id="account" tabindex="-1">账户与资产 <a class="header-anchor" href="#account" aria-label="Permalink to &quot;账户与资产 {#account}&quot;">​</a></h2><p>期权下单资金与普通现货挂单占用未必相同。应明确购买时是扣款、冻结还是其他处理，结算时是发放收益、返还本金还是退单，不能统一称为解冻。</p><h2 id="states" tabindex="-1">订单与周期状态 <a class="header-anchor" href="#states" aria-label="Permalink to &quot;订单与周期状态 {#states}&quot;">​</a></h2><p>已检查的 new-cxex 订单状态定义包含等待购买、购买中、等待交割、交割中、交割完成和退还；另有涨跌平结果相关定义。业务说明中应区分订单处理进度和结果方向。</p><h2 id="price" tabindex="-1">价格依据与结算机制 <a class="header-anchor" href="#price" aria-label="Permalink to &quot;价格依据与结算机制 {#price}&quot;">​</a></h2><p>订单需关联交易产品、规则版本、购买时间、周期、参考价格和收益参数。周期记录应保存用于结果复核的价格依据。触碰产品还需要期间高低价或足够的路径证据。</p><p>结算状态与资金入账结果应可分别查询，避免界面显示“完成”而资产事实缺失。</p>',10)])])}const u=e(i,[["render",c]]);export{_ as __pageData,u as default};
